class Solution:
    def countWinningSequences(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        L = 2 * n + 1
        off = n
        creatures = 'FWE'
        beat = {('F', 'E'), ('W', 'F'), ('E', 'W')}

        def delta(bob, alice):
            if (bob, alice) in beat:
                return 1
            if (alice, bob) in beat:
                return -1
            return 0

        dp = []
        for c in creatures:
            arr = [0] * L
            arr[off + delta(c, s[0])] = 1
            dp.append(arr)

        for i in range(1, n):
            a, b, c = dp
            tot = [(x + y + z) % MOD for x, y, z in zip(a, b, c)]
            ndp = []
            for k, nc in enumerate(creatures):
                cur = dp[k]
                arr = [(tot[j] - cur[j]) % MOD for j in range(L)]
                d = delta(nc, s[i])
                if d == 0:
                    new = arr
                elif d == 1:
                    new = [0] * L
                    new[1:] = arr[:-1]
                else:
                    new = [0] * L
                    new[:-1] = arr[1:]
                ndp.append(new)
            dp = ndp

        ans = 0
        for arr in dp:
            ans += sum(arr[off + 1:])
        return ans % MOD

