class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)  # i increasing -> already sorted

        start = [0] * n
        end = [0] * n
        out = []
        stack = [(0, False)]
        while stack:
            node, done = stack.pop()
            if done:
                out.append(s[node])
                end[node] = len(out)
            else:
                start[node] = len(out)
                stack.append((node, True))
                for ch in reversed(children[node]):
                    stack.append((ch, False))

        dfs_str = ''.join(out)
        t = '#' + '#'.join(dfs_str) + '#'
        m = len(t)
        p = [0] * m
        c = r = 0
        for i in range(m):
            if i < r:
                p[i] = min(r - i, p[2 * c - i])
            a = i - p[i] - 1
            b = i + p[i] + 1
            while a >= 0 and b < m and t[a] == t[b]:
                p[i] += 1
                a -= 1
                b += 1
            if i + p[i] > r:
                c, r = i, i + p[i]

        ans = [False] * n
        for i in range(n):
            l = start[i]
            rr = end[i] - 1
            ans[i] = p[l + rr + 1] >= rr - l + 1
        return ans

