class Solution:
    def subsequencePairCount(self, nums: List[int]) -> int:
        MOD = 10 ** 9 + 7
        M = 201  # posibles gcd: 0 (conjunto vacio) y 1..200

        # Agrupacion de transiciones por elemento: g -> gcd(g, x)  (con gcd(0,x)=x)
        cache = {}

        def grupos(x):
            gr = cache.get(x)
            if gr is None:
                d = {}
                for g in range(M):
                    ng = x if g == 0 else gcd(g, x)
                    d.setdefault(ng, []).append(g)
                gr = list(d.items())
                cache[x] = gr
            return gr

        try:
            import numpy as np

            dp = np.zeros((M, M), dtype=np.int64)
            dp[0, 0] = 1
            idx_cache = {}
            for x in nums:
                gr = idx_cache.get(x)
                if gr is None:
                    gr = [(ng, np.array(idx, dtype=np.intp)) for ng, idx in grupos(x)]
                    idx_cache[x] = gr
                add_r = np.zeros((M, M), dtype=np.int64)
                for ng, idx in gr:
                    # fila destino ng recibe la suma de las filas origen del grupo
                    add_r[ng] = dp[idx].sum(axis=0)
                # dp es simetrica -> la transicion por columnas es la transpuesta
                dp = (dp + add_r + add_r.T) % MOD
            total = int(dp[np.arange(1, M), np.arange(1, M)].sum() % MOD)
            return total
        except ImportError:
            dp = [[0] * M for _ in range(M)]
            dp[0][0] = 1
            for x in nums:
                gr = grupos(x)
                add_r = [[0] * M for _ in range(M)]
                for ng, idx in gr:
                    if len(idx) == 1:
                        add_r[ng] = dp[idx[0]][:]
                    else:
                        add_r[ng] = [sum(col) for col in zip(*(dp[i] for i in idx))]
                add_c = [list(col) for col in zip(*add_r)]
                dp = [
                    [(a + b + c) % MOD for a, b, c in zip(dr, rr, cr)]
                    for dr, rr, cr in zip(dp, add_r, add_c)
                ]
            return sum(dp[g][g] for g in range(1, M)) % MOD

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)

        # g[m] = numero minimo de operaciones para reducir m hasta 1
        g = [0] * (L + 1)
        for m in range(2, L + 1):
            g[m] = 1 + g[bin(m).count('1')]

        # Un x >= 2 con popcount c es k-reducible si 1 + g[c] <= k.
        # x = 1 (popcount 1) es 0-reducible, y cualquier potencia de 2 usa 1 paso (k >= 1).
        valid = [False] * (L + 1)
        for c in range(1, L + 1):
            valid[c] = True if c == 1 else (1 + g[c] <= k)

        # Coeficientes binomiales C[n][r] mod 1e9+7
        C = [[0] * (L + 1) for _ in range(L + 1)]
        for i in range(L + 1):
            C[i][0] = 1
            for j in range(1, i + 1):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

        # DP por prefijos: fijamos s[:i], ponemos 0 donde s[i] == '1',
        # y los rem bits restantes son libres.
        ans = 0
        ones = 0
        for i in range(L):
            if s[i] == '1':
                rem = L - i - 1
                for j in range(rem + 1):
                    c = ones + j
                    if c >= 1 and valid[c]:
                        ans += C[rem][j]
                ans %= MOD
                ones += 1

        return ans % MOD

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)

        # steps[m] = number of operations to reduce m to 1 (m >= 1)
        steps = [0] * (L + 1)
        for m in range(2, L + 1):
            steps[m] = 1 + steps[bin(m).count("1")]

        # Pascal's triangle up to L
        C = [[0] * (L + 1) for _ in range(L + 1)]
        for i in range(L + 1):
            C[i][0] = 1
            for j in range(1, i + 1):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

        ans = 0
        ones = 0  # number of set bits in the fixed prefix s[0..i-1]
        for i in range(L):
            if s[i] == '1':
                free = L - i - 1
                # place a 0 at position i, then anything in the remaining 'free' bits
                for j in range(free + 1):
                    c = ones + j
                    if c >= 1 and 1 + steps[c] <= k:
                        ans = (ans + C[free][j]) % MOD
                ones += 1
        return ans % MOD

