class Solution:
    def minDifference(self, nums: List[int]) -> int:
        n = len(nums)

        # 1) Maximum difference between adjacent pairs where BOTH values are known.
        #    This is a hard lower bound on the answer (we cannot change those).
        base = 0
        for i in range(n - 1):
            a, b = nums[i], nums[i + 1]
            if a != -1 and b != -1:
                d = a - b
                if d < 0:
                    d = -d
                if d > base:
                    base = d

        # 2) Known values that are adjacent to at least one missing element.
        #    Only these constrain the choice of (x, y).
        mn = None
        mx = None
        for i in range(n):
            v = nums[i]
            if v == -1:
                continue
            touches_gap = (i > 0 and nums[i - 1] == -1) or (i + 1 < n and nums[i + 1] == -1)
            if touches_gap:
                if mn is None or v < mn:
                    mn = v
                if mx is None or v > mx:
                    mx = v

        # No missing element touches a known value:
        #  - either there are no -1 at all  -> answer is `base`
        #  - or the whole array is -1       -> answer is 0 (= base)
        if mn is None:
            return base

        # 3) Precompute the maximal runs of -1 with their known boundaries.
        runs = []  # (length, left_known_or_None, right_known_or_None)
        i = 0
        while i < n:
            if nums[i] != -1:
                i += 1
                continue
            j = i
            while j < n and nums[j] == -1:
                j += 1
            left = nums[i - 1] if i > 0 else None
            right = nums[j] if j < n else None
            runs.append((j - i, left, right))
            i = j

        # 4) Feasibility for a candidate answer d.
        #    Claim: if any pair works for d, then the canonical pair
        #    x = mn + d, y = mx - d works too (it maximizes coverage on the
        #    low side and on the high side while never widening |x - y|).
        def feasible(d: int) -> bool:
            x = mn + d
            y = mx - d
            for L, a, b in runs:
                if a is None and b is None:
                    # Whole array missing: fill everything with one value.
                    continue
                if a is None:
                    # Prefix run: fill it all with a single value near b.
                    if abs(x - b) > d and abs(y - b) > d:
                        return False
                elif b is None:
                    # Suffix run: fill it all with a single value near a.
                    if abs(x - a) > d and abs(y - a) > d:
                        return False
                elif L == 1:
                    # A single hole must be covered by ONE value close to both sides.
                    if not ((abs(x - a) <= d and abs(x - b) <= d) or
                            (abs(y - a) <= d and abs(y - b) <= d)):
                        return False
                else:
                    # Length >= 2: pick p next to a and q next to b; the interior
                    # can always be padded (p...p q...q), so the only extra
                    # requirement is |p - q| <= d.
                    ok = False
                    for p in (x, y):
                        if abs(p - a) > d:
                            continue
                        for q in (x, y):
                            if abs(q - b) <= d and abs(p - q) <= d:
                                ok = True
                                break
                        if ok:
                            break
                    if not ok:
                        return False
            return True

        # 5) Binary search on the answer.
        lo, hi = base, max(base, 10 ** 9)
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

