class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        # Any value strictly greater than threshold can never have an edge:
        # lcm(a, b) >= max(a, b) > threshold. Each such value is its own component.
        big = 0
        small = []
        for x in nums:
            if x > threshold:
                big += 1
            else:
                small.append(x)

        if not small:
            return big

        # Two values a, b are connected iff there exists m <= threshold with a | m and b | m
        # (m = lcm(a, b) works, and conversely lcm(a, b) | m <= threshold).
        # So: for every m in 1..threshold, union together all present values dividing m.
        # Implemented by walking multiples of each present value (harmonic sum ~ T * ln T).
        parent = list(range(threshold + 1))

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        comp = len(small)
        rep = [0] * (threshold + 1)  # rep[m] = some present value dividing m (0 = none yet)

        small.sort()
        for v in small:
            for m in range(v, threshold + 1, v):
                r = rep[m]
                if r == 0:
                    rep[m] = v
                else:
                    ra = find(r)
                    rb = find(v)
                    if ra != rb:
                        parent[ra] = rb
                        comp -= 1

        return comp + big

