class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        # Cualquier valor > threshold no puede tener aristas: lcm(x, y) >= max(x, y) > threshold.
        # Cada uno de esos es su propia componente.
        present = bytearray(threshold + 1)
        big = 0
        for v in nums:
            if v > threshold:
                big += 1
            else:
                present[v] = 1

        small = 0
        for i in range(1, threshold + 1):
            if present[i]:
                small += 1

        if small == 0:
            return big

        parent = list(range(threshold + 1))

        def find(x: int) -> int:
            root = x
            while parent[root] != root:
                root = parent[root]
            while parent[x] != root:
                parent[x], x = root, parent[x]
            return root

        comp = small

        # Para cada d, sea mn el menor multiplo de d presente en nums.
        # Para otro multiplo m de d presente: gcd(mn, m) >= d, luego
        # lcm(mn, m) = mn*m/gcd(mn, m) <= mn*m/d; si mn*m/d <= threshold la arista es real.
        # Y toda arista real (x, y) queda cubierta: con d = gcd(x, y) se tiene mn <= min(x, y),
        # asi que mn*x/d <= y*x/d = lcm(x, y) <= threshold y mn*y/d <= threshold,
        # por lo que x e y quedan unidos a traves de mn.
        for d in range(1, threshold + 1):
            mn = 0
            for m in range(d, threshold + 1, d):
                if present[m]:
                    mn = m
                    break
            if mn == 0:
                continue

            limit = threshold * d // mn
            if limit > threshold:
                limit = threshold

            for m in range(mn + d, limit + 1, d):
                if present[m]:
                    ra = find(mn)
                    rb = find(m)
                    if ra != rb:
                        parent[ra] = rb
                        comp -= 1

        return comp + big

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def cost_alternating() -> int:
            # k == 1 requires the whole string to alternate: only two targets.
            c = 0
            for i, ch in enumerate(s):
                if (ch == '1') != (i % 2 == 1):
                    c += 1
            return min(c, n - c)

        def cost_split(k: int) -> int:
            # For k >= 2 every maximal run of length L can be cut with L // (k + 1)
            # interior flips, and interior flips never merge with neighbouring runs.
            total = 0
            i = 0
            while i < n:
                j = i
                while j < n and s[j] == s[i]:
                    j += 1
                total += (j - i) // (k + 1)
                i = j
            return total

        def feasible(k: int) -> bool:
            if k <= 0:
                return False
            if k == 1:
                return cost_alternating() <= numOps
            return cost_split(k) <= numOps

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        # Maximal runs of identical characters.
        runs = []
        i = 0
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            runs.append(j - i)
            i = j

        # m == 1 is special: the whole string must alternate, so the cost is
        # the Hamming distance to the closest of the two alternating patterns.
        d0 = 0  # distance to "0101..."
        for idx, ch in enumerate(s):
            if ch != ('0' if idx % 2 == 0 else '1'):
                d0 += 1
        if min(d0, n - d0) <= numOps:
            return 1

        # For m >= 2 the greedy run-splitting cost is exact: a run of length L
        # needs L // (m + 1) flips, and those flips can always be placed strictly
        # inside the run (so they stay isolated singletons of length 1 <= m).
        def cost(m: int) -> int:
            total = 0
            for L in runs:
                total += L // (m + 1)
                if total > numOps:
                    return total
            return total

        lo, hi = 2, n
        while lo < hi:
            mid = (lo + hi) // 2
            if cost(mid) <= numOps:
                hi = mid
            else:
                lo = mid + 1
        return lo

