class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        def sum_of_max(arr: List[int], k: int) -> int:
            n = len(arr)
            m = k - 1

            # f(t) = #{(x, y) : x >= 0, y >= 0, x + y <= t}
            def f(t: int) -> int:
                if t < 0:
                    return 0
                return (t + 1) * (t + 2) // 2

            # prev[i] = last j < i with arr[j] >= arr[i]  (-1 if none)
            prev = [-1] * n
            stack = []
            for i in range(n):
                x = arr[i]
                while stack and arr[stack[-1]] < x:
                    stack.pop()
                prev[i] = stack[-1] if stack else -1
                stack.append(i)

            # nxt[i] = first j > i with arr[j] > arr[i]  (n if none)
            nxt = [n] * n
            stack = []
            for i in range(n - 1, -1, -1):
                x = arr[i]
                while stack and arr[stack[-1]] <= x:
                    stack.pop()
                nxt[i] = stack[-1] if stack else n
                stack.append(i)

            fm = f(m)
            total = 0
            for i in range(n):
                A = i - prev[i]          # choices of start offset x in [0, A)
                B = nxt[i] - i           # choices of end offset y in [0, B)
                cnt = fm - f(m - A) - f(m - B) + f(m - A - B)
                if cnt:
                    total += arr[i] * cnt
            return total

        return sum_of_max(nums, k) - sum_of_max([-v for v in nums], k)

