        P = int(data[idx]); idx += 1
        B = int(data[idx]); idx += 1
        Q = int(data[idx]); idx += 1
        procs.append((A, P, B, Q))

    def min_cost(A, P, B, Q, W, cap):
        # Minimum cost to reach capacity >= W for one process.
        # In an optimal solution either (#S units) < B or (#T units) < A,
        # because B units of S and A units of T both give throughput A*B,
        # so one could be swapped for the cheaper of the two.
        best = None
        # enumerate number of S machines i in [0, B-1]
        for i in range(B):
            rem = W - i * A
            if rem <= 0:
                j = 0
            else:
                j = (rem + B - 1) // B
            c = i * P + j * Q
            if best is None or c < best:
                best = c
            if rem <= 0:
                break
        # enumerate number of T machines j in [0, A-1]
        for j in range(A):
            rem = W - j * B
            if rem <= 0:
                i = 0
            else:
                i = (rem + A - 1) // A
            c = i * P + j * Q
            if c < best:
                best = c
            if rem <= 0:
                break
        return best

    def feasible(W):
        if W <= 0:
            return True
        total = 0
        for (A, P, B, Q) in procs:
            total += min_cost(A, P, B, Q, W, X)
            if total > X:
                return False
        return total <= X

    lo = 0
    hi = 10 ** 9 + 1  # upper bound: X <= 1e7, throughput per yen <= 100
    # find max W with feasible(W)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    sys.stdout.write(str(lo) + "\n")

