import sys

def main():
    data = sys.stdin.buffer.read().split()
    idx = 0
    n = int(data[idx]); idx += 1
    x = int(data[idx]); idx += 1
    procs = []
    for _ in range(n):
        a = int(data[idx]); idx += 1
        p = int(data[idx]); idx += 1
        b = int(data[idx]); idx += 1
        q = int(data[idx]); idx += 1
        procs.append((a, p, b, q))

    INF = float('inf')

    def cost_proc(a, p, b, q, w, cap):
        # minimum cost to get capacity >= w for this process
        # exchange argument: b units of S give a*b capacity at cost b*p,
        # a units of T give a*b capacity at cost a*q, so it suffices to
        # consider < b units of S (rest with T) or < a units of T (rest with S)
        best = INF
        # i units of S, rest with T
        for i in range(b + 1):
            c = i * p
            if c >= best or c > cap:
                if c > cap and c >= best:
                    break
                if c >= best:
                    continue
            rem = w - i * a
            if rem <= 0:
                if c < best:
                    best = c
                break
            c += ((rem + b - 1) // b) * q
            if c < best:
                best = c
        # j units of T, rest with S
        for j in range(a + 1):
            c = j * q
            if c > cap and c >= best:
                break
            rem = w - j * b
            if rem <= 0:
                if c < best:
                    best = c
                break
            c += ((rem + a - 1) // a) * p
            if c < best:
                best = c
        return best

    def feasible(w):
        if w <= 0:
            return True
        total = 0
        for (a, p, b, q) in procs:
            budget_left = x - total
            c = cost_proc(a, p, b, q, w, budget_left)
            if c == INF:
                return False
            total += c
            if total > x:
                return False
        return total <= x

    lo = 0
    hi = 10 ** 9 + 1  # capacity is at most X * max(A/P, B/Q) <= 1e7 * 100
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    print(lo)

