import sys

def main():
    sys.setrecursionlimit(10000)
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    strs = data[1:1 + n]

    used = set()
    edges = []
    for s in strs:
        u = ord(s[0]) - 65
        v = ord(s[1]) - 65
        used.add(u)
        used.add(v)
        edges.append((u, v))

    # transitive closure (paths of length >= 1)
    reach = [[False] * 26 for _ in range(26)]
    for u, v in edges:
        reach[u][v] = True
    for k in range(26):
        rk = reach[k]
        for i in range(26):
            if reach[i][k]:
                ri = reach[i]
                for j in range(26):
                    if rk[j]:
                        ri[j] = True

    # strongly connected components by mutual reachability
    comp = [-1] * 26
    comps = []
    order = sorted(used)
    for u in order:
        if comp[u] != -1:
            continue
        cid = len(comps)
        comp[u] = cid
        members = [u]
        for v in order:
            if v != u and comp[v] == -1 and reach[u][v] and reach[v][u]:
                comp[v] = cid
                members.append(v)
        comps.append(members)

    m = len(comps)
    # an SCC has internal edges iff some cycle passes through it (covers self loops too)
    has_internal = [reach[c[0]][c[0]] for c in comps]

    cross = {}
    for u, v in edges:
        cu = comp[u]
        cv = comp[v]
        if cu != cv:
            key = (cu, cv)
            cross[key] = cross.get(key, 0) + 1

    incident = [False] * m
    for (a, b) in cross:
        incident[a] = True
        incident[b] = True

    # SCCs with internal edges but no cross edge need their own string
    extra = 0
    for c in range(m):
        if has_internal[c] and not incident[c]:
            extra += 1

    if not cross:
        print(extra)
        return

    INF = 1 << 50

    class Dinic:
        def __init__(self, num):
            self.n = num
            self.g = [[] for _ in range(num)]
            self.level = [-1] * num
            self.it = [0] * num

        def add(self, u, v, cap):
            self.g[u].append([v, cap, len(self.g[v])])
            self.g[v].append([u, 0, len(self.g[u]) - 1])
            return (u, len(self.g[u]) - 1)

        def bfs(self, s, t):
            self.level = [-1] * self.n
            self.level[s] = 0
            q = [s]
            for u in q:
                for e in self.g[u]:
                    if e[1] > 0 and self.level[e[0]] < 0:
                        self.level[e[0]] = self.level[u] + 1
                        q.append(e[0])
            return self.level[t] >= 0

        def dfs(self, u, t, f):
            if u == t:
                return f
            while self.it[u] < len(self.g[u]):
                e = self.g[u][self.it[u]]
                v = e[0]
                if e[1] > 0 and self.level[v] == self.level[u] + 1:
                    d = self.dfs(v, t, min(f, e[1]))
                    if d > 0:
                        e[1] -= d
                        self.g[v][e[2]][1] += d
                        return d
                self.it[u] += 1
            return 0

        def maxflow(self, s, t):
            flow = 0
            while self.bfs(s, t):
                self.it = [0] * self.n
                while True:
                    f = self.dfs(s, t, INF)
                    if f == 0:
                        break
                    flow += f
            return flow

    # minimum flow with lower bounds:
    # every cross edge (multiplicity = lower bound) must be traversed;
    # paths may start/end at any component (S -> any, any -> T).
    S = m
    T = m + 1
    SS = m + 2
    TT = m + 3
    din = Dinic(m + 4)
    deg = [0] * (m + 2)

    for (a, b), cnt in cross.items():
        din.add(a, b, INF)          # capacity INF - lower bound (INF stays INF)
        deg[b] += cnt
        deg[a] -= cnt

    for x in range(m):
        din.add(S, x, INF)
        din.add(x, T, INF)

    for v in range(m + 2):
        if deg[v] > 0:
            din.add(SS, v, deg[v])
        elif deg[v] < 0:
            din.add(v, TT, -deg[v])

    din.maxflow(SS, TT)
    _, idx = din.add(T, S, INF)
    din.maxflow(SS, TT)

    e = din.g[T][idx]
    minflow = din.g[S][e[2]][1]

    print(minflow + extra)

