    reach = [0] * 26
    used = [False] * 26
    for s in strs:
        a = ord(s[0]) - 65
        b = ord(s[1]) - 65
        reach[a] |= 1 << b
        used[a] = True
        used[b] = True

    # Transitive closure (Floyd-Warshall with bitmasks)
    for k in range(26):
        bk = reach[k]
        if bk == 0:
            continue
        for i in range(26):
            if (reach[i] >> k) & 1:
                reach[i] |= bk

    # Strongly connected components among used vertices
    comp = [-1] * 26
    reps = []
    for i in range(26):
        if not used[i] or comp[i] != -1:
            continue
        cid = len(reps)
        comp[i] = cid
        for j in range(i + 1, 26):
            if used[j] and comp[j] == -1 and ((reach[i] >> j) & 1) and ((reach[j] >> i) & 1):
                comp[j] = cid
        reps.append(i)

    m = len(reps)
    if m == 0:
        print(0)
        return

    # DAG of SCCs, as a partial order (reachability between distinct components)
    adj = [[] for _ in range(m)]
    for i in range(m):
        ri = reach[reps[i]]
        for j in range(m):
            if i != j and ((ri >> reps[j]) & 1):
                adj[i].append(j)

    # Minimum chain cover = m - maximum bipartite matching (Kuhn)
    match_r = [-1] * m

    def try_kuhn(v, visited):
        stack = [(v, 0)]
        path = []
        # iterative Kuhn to avoid recursion issues (m <= 26 anyway)
        while stack:
            u, idx = stack.pop()
            found = False
            lst = adj[u]
            while idx < len(lst):
                to = lst[idx]
                idx += 1
                if not visited[to]:
                    visited[to] = True
                    if match_r[to] == -1:
                        match_r[to] = u
                        for (pu, pto) in reversed(path):
                            match_r[pto] = pu
                        return True
                    stack.append((u, idx))
                    path.append((u, to))
                    stack.append((match_r[to], 0))
                    found = True
                    break
            if not found:
                if path:
                    path.pop()
        return False

    res = 0
    for v in range(m):
        visited = [False] * m
        if try_kuhn(v, visited):
            res += 1

    print(m - res)


