    for i in range(1, maxn + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (maxn + 1)
    inv_fact[maxn] = pow(fact[maxn], MOD - 2, MOD)
    for i in range(maxn, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def comb(n, r):
        if r < 0 or n < 0 or r > n:
            return 0
        return fact[n] * inv_fact[r] % MOD * inv_fact[n - r] % MOD

    # H[u] = number of surjective strings of length u+kk onto kk fixed letters
    H = [0] * (L + 1)
    for i in range(kk + 1):
        base = kk - i
        coef = comb(kk, i)
        if i & 1:
            coef = (MOD - coef) % MOD
        if coef == 0:
            continue
        cur = pow(base, kk, MOD)
        bm = base % MOD
        for u in range(L + 1):
            if cur:
                H[u] = (H[u] + coef * cur) % MOD
            cur = cur * bm % MOD

    def polymul(a, b):
        res = [0] * (L + 1)
        for i in range(L + 1):
            ai = a[i]
            if ai:
                lim = L - i
                for j in range(lim + 1):
                    bj = b[j]
                    if bj:
                        res[i + j] = (res[i + j] + ai * bj) % MOD
        return res

    # H^M truncated at degree L
    res = [0] * (L + 1)
    res[0] = 1
    bp = H[:]
    e = M
    while e > 0:
        if e & 1:
            res = polymul(res, bp)
        e >>= 1
        if e:
            bp = polymul(bp, bp)

    # multiply by 1/(1-(K-2)z)^d  (coefficient of z^b is C(b+d-1,d-1)*(K-2)^b)
    q = (K - 2) % MOD
    ans = 0
    for b in range(L + 1):
        if d == 0:
            c = 1 if b == 0 else 0
        else:
            c = comb(b + d - 1, d - 1) * pow(q, b, MOD) % MOD
        if c:
            ans = (ans + c * res[L - b]) % MOD

    print(ans % MOD)

main()

import sys


def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    m = int(data[1])
    L = [0] * m
    R = [0] * m
    p = 2
    for i in range(m):
        L[i] = int(data[p])
        R[i] = int(data[p + 1])
        p += 2

    out = sys.stdout

    def answer(pairs):
        res = ['0'] * m
        for i, o in pairs:
            res[i] = str(o)
        out.write(str(len(pairs)) + '\n')
        out.write(' '.join(res) + '\n')

    # --- cost 1: a single interval equal to [1, n] ---
    for i in range(m):
        if L[i] == 1 and R[i] == n:
            answer([(i, 1)])
            return

    # --- cost 2 ---
    # (c) two disjoint intervals -> op2 on both
    imin = 0
    imax = 0
    for i in range(1, m):
        if R[i] < R[imin]:
            imin = i
        if L[i] > L[imax]:
            imax = i
    if R[imin] < L[imax]:
        answer([(imin, 2), (imax, 2)])
        return

    # (a) op1 + op1 : one starting at 1, one ending at n, overlapping/adjacent
    bi = -1
    bj = -1
    for i in range(m):
        if L[i] == 1 and (bi == -1 or R[i] > R[bi]):
            bi = i
        if R[i] == n and (bj == -1 or L[i] < L[bj]):
            bj = i
    if bi != -1 and bj != -1 and bi != bj and L[bj] <= R[bi] + 1:
        answer([(bi, 1), (bj, 1)])
        return

    # (b) op1 on i + op2 on j with [Lj,Rj] contained in [Li,Ri]
    order = sorted(range(m), key=lambda i: (L[i], -R[i]))
    best = -1
    for k in order:
        if best != -1 and R[best] >= R[k]:
            answer([(best, 1), (k, 2)])
            return
        if best == -1 or R[k] > R[best]:
            best = k

    # --- cost 3 ---
    # Here no two intervals are disjoint, so max(L) <= min(R): every interval
    # contains [Lmax, Rmin].  op2 on an interval attaining Lmax, op2 on one
    # attaining Rmin, op1 on any third interval.
    if m >= 3:
        Lmax = L[imax]
        Rmin = R[imin]
        a = imax
        b = imin
        if a == b:
            alt = -1
            for i in range(m):
                if i != a and L[i] == Lmax:
                    alt = i
                    break
            if alt != -1:
                a = alt
            else:
                for i in range(m):
                    if i != b and R[i] == Rmin:
                        b = i
                        break
        if a != b:
            c = -1
            for i in range(m):
                if i != a and i != b:
                    c = i
                    break
            if c != -1:
                answer([(a, 2), (b, 2), (c, 1)])
                return

    out.write('-1\n')


main()

import sys

try:
    import numpy as np
    HAVE_NP = True
except Exception:
    HAVE_NP = False


def _mul_np(X, Y, mod):
    # X, Y are int64 numpy arrays with entries in [0, mod)
    hi = X >> 15
    lo = X & 32767
    return (((hi.dot(Y) % mod) << 15) + lo.dot(Y)) % mod


def _mul_py(X, Y, mod, n):
    R = []
    for row in X:
        acc = [0] * n
        for k in range(n):
            a = row[k]
            if a:
                yr = Y[k]
                acc = [(u + a * v) for u, v in zip(acc, yr)]
        R.append([u % mod for u in acc])
    return R


def mat_pow(A, e, mod, n):
    if HAVE_NP:
        M = np.array(A, dtype=np.int64) % mod
        R = np.eye(n, dtype=np.int64) % mod
        while e > 0:
            if e & 1:
                R = _mul_np(R, M, mod)
            e >>= 1
            if e:
                M = _mul_np(M, M, mod)
        return R.tolist()
    else:
        M = [[v % mod for v in row] for row in A]
        R = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
        R = [[v % mod for v in row] for row in R]
        while e > 0:
            if e & 1:
                R = _mul_py(R, M, mod, n)
            e >>= 1
            if e:
                M = _mul_py(M, M, mod, n)
        return R


def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    p = int(data[1])
    pos = 2
    A = []
    for _ in range(n):
        A.append([int(x) for x in data[pos:pos + n]])
        pos += n

    out = []

    if p == 2:
        # Only one possible B: every zero must become 1.
        B = [[(1 if v == 0 else v) for v in row] for row in A]
        M = mat_pow(B, 2, 2, n)
        for i in range(n):
            out.append(' '.join(str(M[i][j] % 2) for j in range(n)))
        sys.stdout.write('\n'.join(out) + '\n')
        return

    K = 0
    for row in A:
        for v in row:
            if v == 0:
                K += 1

    # Walks using no variable edge.
    M = mat_pow(A, p, p, n)

    # Walks using exactly one variable position, exactly p-1 times,
    # plus exactly one fixed (nonzero) edge.
    S = [[0] * n for _ in range(n)]
    for i in range(n):
        Ai = A[i]
        aii_zero = (A[i][i] == 0)
        for j in range(n):
            a = Ai[j]
            if a:
                c = 0
                if A[j][j] == 0:
                    c += 1
                if aii_zero:
                    c += 1
                if c:
                    S[i][j] = (a * c) % p

    if p == 3:
        # a != b is only possible when p-1 == 2: walk a -> b -> a -> b
        for a in range(n):
            for b in range(n):
                if a != b and A[a][b] == 0 and A[b][a] != 0:
                    S[a][b] = (S[a][b] + A[b][a]) % p

    sign = 1 if (K % 2 == 0) else -1
    for i in range(n):
        Mi = M[i]
        Si = S[i]
        out.append(' '.join(str((sign * (Mi[j] + Si[j])) % p) for j in range(n)))
    sys.stdout.write('\n'.join(out) + '\n')


main()

import sys


def mat_pow(A, e, n, p):
    """A^e mod p, A given as list of lists, returns list of lists."""
    try:
        import numpy as np
    except Exception:
        np = None

    if np is not None:
        base = np.array(A, dtype=np.int64) % p
        R = np.eye(n, dtype=np.int64) % p
        MASK = (1 << 15) - 1

        def mul(X, Y):
            Yh = Y >> 15
            Yl = Y & MASK
            return (((X.dot(Yh) % p) << 15) + X.dot(Yl)) % p

        while e:
            if e & 1:
                R = mul(R, base)
            e >>= 1
            if e:
                base = mul(base, base)
        return [[int(x) for x in row] for row in R]

    # pure python fallback
    def mul_py(X, Y):
        res = []
        for i in range(n):
            Xi = X[i]
            row = [0] * n
            for k in range(n):
                a = Xi[k]
                if a:
                    Yk = Y[k]
                    row = [x + a * y for x, y in zip(row, Yk)]
            res.append([v % p for v in row])
        return res

    base = [[A[i][j] % p for j in range(n)] for i in range(n)]
    R = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    R = [[v % p for v in row] for row in R]
    while e:
        if e & 1:
            R = mul_py(R, base)
        e >>= 1
        if e:
            base = mul_py(base, base)
    return R


def main():
    data = sys.stdin.buffer.read().split()
    N = int(data[0])
    p = int(data[1])
    vals = data[2:2 + N * N]
    A = [[int(vals[i * N + j]) for j in range(N)] for i in range(N)]

    if p == 2:
        # every zero must become 1, and entries are in {0,1}: B is the all-ones matrix
        v = N % 2
        line = ' '.join([str(v)] * N)
        sys.stdout.write('\n'.join([line] * N) + '\n')
        return

    K = 0
    for i in range(N):
        Ai = A[i]
        for j in range(N):
            if Ai[j] == 0:
                K += 1

    # T: contribution of paths using exactly one zero cell (repeated p-1 times)
    T = [[0] * N for _ in range(N)]
    for a in range(N):
        if A[a][a] == 0:
            for i in range(N):
                if A[i][a]:
                    T[i][a] = (T[i][a] + A[i][a]) % p
            Aa = A[a]
            for j in range(N):
                if Aa[j]:
                    T[a][j] = (T[a][j] + Aa[j]) % p

    if p == 3:
        for a in range(N):
            Aa = A[a]
            for b in range(N):
                if a != b and Aa[b] == 0 and A[b][a]:
                    T[a][b] = (T[a][b] + A[b][a]) % p

    M = mat_pow(A, p, N, p)

    sign = 1 if (K % 2 == 0) else (p - 1)

    out = []
    for i in range(N):
        Mi = M[i]
        Ti = T[i]
        row = [str((sign * ((Mi[j] + Ti[j]) % p)) % p) for j in range(N)]
        out.append(' '.join(row))
    sys.stdout.write('\n'.join(out) + '\n')


main()
